tokens.css:
--color-bg: #faf5ee;
--color-surface: #f4ebdf;
--color-text: #2b2420;
--color-text-muted: #7a6b5e;
--color-border: #e2d6c6;
--color-primary: #2a1f61;
--color-on-primary: #ffffff;
--color-accent: #f26554;
--color-on-accent: #1f1a17;
--font-display: "Fraunces", Georgia, serif;
--font-body: "Work Sans", system-ui, sans-serif;
--text-sm: 14px;
--text-base: 17px;
--text-lg: 21px;
--text-xl: 27px;
--text-2xl: 33px;
--text-3xl: 42px;
--radius-control: 8px;
--radius-card: 12px;
--space-section: 120px;
--shadow-card: 0 1px 2px color-mix(in oklab, var(--color-text) 8%, transparent), 0 10px 30px color-mix(in oklab, var(--color-text) 12%, transparent);
